<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,approvalLabel,dateTime,type Row} from './api';
import AppIcon from './AppIcon.vue';
import DataChart from './DataChart.vue';
const emit=defineEmits<{navigate:[page:string]}>();
const days=ref(14),loading=ref(false),error=ref(''),data=ref<Row|null>(null);let sequence=0;
async function refresh(){const current=++sequence;loading.value=true;error.value='';try{const result=await api<Row>('/api/overview?days='+days.value);if(current===sequence)data.value=result}catch(e){if(current===sequence)error.value=(e as Error).message}finally{if(current===sequence)loading.value=false}}
const rates=computed(()=>{const r=data.value?.requests,a=data.value?.approvals,t=data.value?.agents;return {requests:r?.requests?Number(r.completed)/Number(r.requests)*100:null,approvals:Number(a?.approved)+Number(a?.rejected)?Number(a.approved)/(Number(a.approved)+Number(a.rejected))*100:null,agents:t?.total?Number(t.active)/Number(t.total)*100:null}});
const cards=computed(()=>[{label:'读取请求总数',value:data.value?.requests.requests,rate:rates.value.requests,caption:'成功率',note:'近 '+days.value+' 天'},{label:'已完成审批',value:data.value?Number(data.value.approvals.approved)+Number(data.value.approvals.rejected):null,rate:rates.value.approvals,caption:'通过率',note:'近 '+days.value+' 天'},{label:'我的有效 Agent',value:data.value?.agents.active,rate:rates.value.agents,caption:'有效占比',note:data.value?'共 '+data.value.agents.total+' 个凭据':'—'}]);
const trafficSeries=[{key:'requests',label:'读取请求',color:'#2f75ff'},{key:'approvals',label:'审批申请',color:'#20bf82'}];
const qualitySeries=[{key:'completed',label:'读取成功',color:'#12a594'},{key:'denied',label:'已拒绝',color:'#ff993d'},{key:'failed',label:'执行失败',color:'#f45467'}];
const approvalSeries=[{key:'approved',label:'已通过',color:'#12a594'},{key:'rejected',label:'已拒绝',color:'#0090ff'}];
const outcomes=computed(()=>[{name:'读取成功',value:Number(data.value?.requests.completed||0)},{name:'已拒绝',value:Number(data.value?.requests.denied||0)},{name:'执行失败',value:Number(data.value?.requests.failed||0)}]);
const outcomeSeries=qualitySeries.map(s=>({...s,key:'value'}));
const hasActivity=computed(()=>Number(data.value?.requests.requests||0)+Number(data.value?.approvals.total||0)>0);
const number=(value:unknown)=>value==null?'—':Number(value).toLocaleString();
onMounted(refresh);watch(days,refresh);defineExpose({refresh});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"><template #action><a-button size="small" @click="refresh">重试</a-button></template></a-alert>
 <a-spin :spinning="loading"><section class="dg-visual-welcome"><div><h2>欢迎回来，数据安全工作台</h2><p>统一管理 MySQL 数据访问、白名单、内部审批和 MCP Agent 凭据。所有指标来自当前账户有权查看的实际数据。</p></div><span class="welcome-mark">{{data?.scope==='PLATFORM'?'全平台安全视图':'我的安全视图'}}</span></section><div class="dg-quick-actions"><button v-if="data?.scope==='PLATFORM'" @click="emit('navigate','sources')"><AppIcon name="sources"/>管理数据源与白名单 →</button><button @click="emit('navigate','approvals')"><AppIcon name="approvals"/>处理读取审批 →</button><button @click="emit('navigate','agents')"><AppIcon name="agents"/>管理 Agent 凭据 →</button></div><div class="dg-toolbar"><div class="dg-toolbar-tab">访问概况<span class="dg-scope">{{data?.scope==='PLATFORM'?'全平台':'我的数据'}}</span></div><div class="dg-date-controls"><span v-if="data" class="dg-period">{{data.from}} — {{data.to}}</span><a-radio-group v-model:value="days" size="small" button-style="solid"><a-radio-button :value="7">近7天</a-radio-button><a-radio-button :value="14">近14天</a-radio-button><a-radio-button :value="30">近30天</a-radio-button></a-radio-group></div></div>
 <div class="dg-overview-grid"><div class="dg-overview-main">
  <section class="dg-kpi-grid"><article v-for="card in cards" :key="card.label" class="dg-kpi" :class="{compact:card.rate==null}"><div class="dg-kpi-title">{{card.label}}</div><div class="dg-kpi-body"><div><strong>{{number(card.value)}}</strong><small>{{card.note}}</small></div><div v-if="card.rate!=null" class="dg-ring"><a-progress type="circle" :width="76" :stroke-width="6" :percent="card.rate" :format="()=>''" stroke-color="#2f75ff" trail-color="#eaf2ff"/><div class="dg-ring-label"><b>{{card.rate.toFixed(1)+'%'}}</b><small>{{card.caption}}</small></div></div></div></article></section>
  <template v-if="hasActivity"><section class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>请求趋势</h2><span>近 {{days}} 天</span></header><div class="dg-legend"><span v-for="series in trafficSeries" :key="series.key"><i :style="{background:series.color}"/>{{series.label}}</span></div><DataChart title="每日读取与审批请求" :data="data?.trends||[]" :series="trafficSeries" :height="246"/></section>
  <section class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>访问质量</h2><span>请求结果</span></header><div class="dg-legend"><span v-for="series in qualitySeries" :key="series.key"><i :style="{background:series.color}"/>{{series.label}}</span></div><DataChart title="读取成功、拒绝和失败趋势" kind="line" :data="data?.trends||[]" :series="qualitySeries" :height="235"/></section>
  <section class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>审批统计</h2><span>按申请日期</span></header><div class="dg-legend"><span v-for="series in approvalSeries" :key="series.key"><i :style="{background:series.color}"/>{{series.label}}</span></div><DataChart title="每日审批处理结果" :data="data?.trends||[]" :series="approvalSeries" :height="225"/></section></template>
  <section v-else class="dg-panel dg-overview-empty"><AppIcon name="dashboard"/><strong>暂无访问记录</strong><a-button type="primary" @click="emit('navigate','agents')">创建 Agent</a-button></section>
 </div><aside class="dg-overview-aside">
  <section v-if="hasActivity" class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>请求结果</h2><span>近 {{days}} 天</span></header><DataChart title="读取请求结果分布" kind="donut" :data="outcomes" :series="outcomeSeries" :height="210"/><div class="dg-distribution"><div v-for="(outcome,index) in outcomes" :key="outcome.name"><span><i :style="{background:qualitySeries[index].color}"/>{{outcome.name}}</span><strong>{{number(outcome.value)}}</strong></div></div></section>
  <section class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>资源概况</h2></header><div class="dg-resource-row"><span class="dg-resource-icon"><AppIcon name="sources"/></span><div><small>{{data?.scope==='PLATFORM'?'已启用数据源':'已授权数据源'}}</small><strong>{{number(data?.sources.enabled)}}<em v-if="data?.scope==='PLATFORM'"> / {{data?.sources.total}}</em></strong></div><button class="dg-icon-button" aria-label="查看数据源" @click="emit('navigate',data?.scope==='PLATFORM'?'sources':'approvals')"><AppIcon name="right"/></button></div><div class="dg-resource-row"><span class="dg-resource-icon blue"><AppIcon name="agents"/></span><div><small>有效 Agent 凭据</small><strong>{{number(data?.agents.active)}}<em> / {{data?.agents.total??'—'}}</em></strong></div><button class="dg-icon-button" aria-label="查看我的 Agent" @click="emit('navigate','agents')"><AppIcon name="right"/></button></div></section>
  <section class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>待处理事项</h2></header><button class="dg-todo" @click="emit('navigate','approvals')"><span><AppIcon name="approvals"/>待我审批</span><strong>{{number(data?.pendingApprovals)}}</strong><AppIcon name="right"/></button><button v-if="data?.scope==='PLATFORM'" class="dg-todo" @click="emit('navigate','alerts')"><span><AppIcon name="alerts"/>安全告警</span><strong>{{number(data?.openAlerts)}}</strong><AppIcon name="right"/></button></section>
  <section v-if="data?.recentApprovals.length" class="dg-panel dg-chart-panel"><header class="dg-section-head"><h2>近期审批</h2></header><div v-for="item in data?.recentApprovals||[]" :key="item.id" class="dg-recent-item"><div><strong>{{item.tableName}}</strong><small>{{item.sourceName}}</small><small>{{dateTime(item.createdAt)}}</small></div><span class="dg-badge" :class="{muted:item.status!=='APPROVED'}">{{approvalLabel(item.status)}}</span></div></section>
 </aside></div></a-spin>
</template>
